// Conditional notification workflow used by worker forms and isolated draft previews.
export const NOTIFICATION_RUNTIME = "// Notification controls use the same STATE.values as ordinary checklist answers.\n// One record is created per equipment instance and triggering operation.\nfunction __tmhNoticeApplies(field,answer,iid){\n  var n=field&&field.notification;\n  if(!n||n.enabled!==true)return false;\n  if(n.trigger==='conditions'){\n    var rules=Array.isArray(n.conditions)?n.conditions:[];\n    if(!rules.length)return false;\n    var matches=rules.map(function(r){return String(getVal(iid,r.fieldKey))===String(r.value);});\n    return n.logic==='any'?matches.some(Boolean):matches.every(Boolean);\n  }\n  if(!answer)return false;\n  if(n.trigger==='always')return true;\n  if(n.trigger==='answers')return Array.isArray(n.answers)&&n.answers.includes(answer);\n  return Array.isArray(field.ok)&&field.ok.length>0&&!field.ok.includes(answer);\n}\nfunction __tmhNoticeItems(){\n  var result=[],selected=STATE.selected||[],sectionsSelected=STATE.selectedSections||[];\n  (EQUIPMENT||[]).forEach(function(eq){\n    if(selected.length&&!selected.includes(eq.id)||typeof eq.instances!=='function')return;\n    eq.instances().forEach(function(inst,index){\n      if(sectionsSelected.length&&!sectionsSelected.includes(inst.section))return;\n      var iid=instId(eq.id,inst,index);\n      (eq.fields||[]).forEach(function(field){\n        var answer=getVal(iid,field.key);\n        if(!__tmhNoticeApplies(field,answer,iid))return;\n        var key=field.key+'_notification_';\n        result.push({iid:iid,eq:eq,inst:inst,field:field,answer:answer,rule:field.notification,\n          status:getVal(iid,key+'status'),photo:getVal(iid,key+'photo'),\n          reason:getVal(iid,key+'reason'),time:getVal(iid,key+'time')});\n      });\n    });\n  });\n  return result;\n}\nfunction __tmhNoticeProgress(){\n  var total=0,filled=0;\n  __tmhNoticeItems().forEach(function(x){\n    total++;if(x.status==='Да'||x.status==='Нет')filled++;\n    if(x.status==='Да'&&x.rule.requirePhoto!==false){total++;if(x.photo)filled++;}\n    if(x.status==='Нет'&&x.rule.requireReason!==false){total++;if(String(x.reason||'').trim())filled++;}\n  });\n  return {total:total,filled:filled};\n}\nfunction __tmhNoticeValidation(){\n  var errors=[];\n  __tmhNoticeItems().forEach(function(x){\n    var name=x.eq.title+' / '+(x.inst.section||'')+' / '+(x.inst.block||'')+' / '+x.field.label;\n    if(x.status!=='Да'&&x.status!=='Нет')errors.push(name+': не указан статус уведомления');\n    else if(x.status==='Да'&&x.rule.requirePhoto!==false&&!x.photo)errors.push(name+': отсутствует фото подтверждения');\n    else if(x.status==='Нет'&&x.rule.requireReason!==false&&!String(x.reason||'').trim())errors.push(name+': не указана причина');\n  });\n  return errors;\n}\nfunction __tmhNoticeOpenPhoto(src){\n  if(!src)return;\n  var overlay=document.createElement('div');\n  overlay.style.cssText='position:fixed;inset:0;z-index:99999;background:#000c;display:flex;align-items:center;justify-content:center;padding:12px';\n  var img=document.createElement('img');img.src=src;img.alt='Фото подтверждения уведомления';\n  img.style.cssText='max-width:96vw;max-height:85vh;object-fit:contain;border-radius:10px';\n  overlay.appendChild(img);overlay.addEventListener('click',function(){overlay.remove();});document.body.appendChild(overlay);\n}\nfunction __tmhNoticeFile(file,done){\n  if(!file||!/^image\\//.test(file.type)){showToast('Выберите фотографию');return;}\n  if(file.size>12*1024*1024){showToast('Фотография должна быть меньше 12 МБ');return;}\n  var reader=new FileReader();\n  reader.onload=function(){\n    var image=new Image();\n    image.onload=function(){\n      var scale=Math.min(1,1200/Math.max(image.width,image.height));\n      var canvas=document.createElement('canvas');canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);\n      var ctx=canvas.getContext('2d');if(!ctx){showToast('Не удалось обработать фотографию');return;}\n      ctx.drawImage(image,0,0,canvas.width,canvas.height);\n      done(canvas.toDataURL('image/jpeg',.7));\n    };\n    image.onerror=function(){showToast('Не удалось открыть фотографию');};\n    image.src=reader.result;\n  };\n  reader.onerror=function(){showToast('Не удалось прочитать фотографию');};\n  reader.readAsDataURL(file);\n}\n// Extend, rather than replace, the existing operation renderer.\nvar __tmhBaseFieldRow=fieldRow;\nfieldRow=function(eq,inst,iid,field){\n  var row=__tmhBaseFieldRow(eq,inst,iid,field),n=field.notification;\n  if(!n||n.enabled!==true)return row;\n  var key=field.key+'_notification_';\n  var box=document.createElement('section');box.className='tmh-notification-control';\n  box.style.cssText='display:none;margin:10px 0;padding:11px;border:1px solid #dfb752;border-left:4px solid #d49b12;border-radius:9px;background:#fff9e8;color:#624a12';\n  var head=document.createElement('strong');head.textContent='⚠ Требуется уведомление';box.appendChild(head);\n  var caption=document.createElement('div');caption.textContent='Уведомление по операции передано?';caption.style.cssText='font-size:13px;margin:8px 0';box.appendChild(caption);\n  var status=document.createElement('select');status.setAttribute('aria-label','Уведомление передано');\n  status.style.cssText='width:100%;min-height:40px;border:1px solid #d8bf89;border-radius:7px;padding:8px;background:#fff;color:#263b4e';\n  [['','— Выберите —'],['Да','Да, уведомление передано'],['Нет','Нет, уведомление не передано']].forEach(function(entry){\n    var option=document.createElement('option');option.value=entry[0];option.textContent=entry[1];status.appendChild(option);\n  });status.value=getVal(iid,key+'status');box.appendChild(status);\n  var yes=document.createElement('div');yes.style.cssText='margin-top:9px';\n  var choose=document.createElement('label');choose.textContent='📷 Фото подтверждения'+(n.requirePhoto!==false?' *':'');\n  choose.style.cssText='display:inline-block;padding:8px 12px;background:#e8f1ff;border:1px solid #b5cdec;border-radius:7px;cursor:pointer;font-size:13px';\n  var file=document.createElement('input');file.type='file';file.accept='image/*';file.style.display='none';\n  choose.appendChild(file);yes.appendChild(choose);\n  var thumbnail=document.createElement('button');thumbnail.type='button';thumbnail.textContent='Просмотреть фото';\n  thumbnail.style.cssText='margin-left:8px;padding:8px;border:1px solid #b5cdec;border-radius:7px;background:white;cursor:zoom-in';\n  thumbnail.onclick=function(){__tmhNoticeOpenPhoto(getVal(iid,key+'photo'));};yes.appendChild(thumbnail);box.appendChild(yes);\n  var no=document.createElement('div');no.style.cssText='margin-top:9px';\n  var reason=document.createElement('textarea');reason.placeholder='Причина отсутствия уведомления'+(n.requireReason!==false?' (обязательно)':'');\n  reason.style.cssText='box-sizing:border-box;width:100%;min-height:64px;padding:8px;border:1px solid #d8bf89;border-radius:7px;background:white;color:#263b4e';\n  reason.value=getVal(iid,key+'reason');no.appendChild(reason);box.appendChild(no);\n  var warning=document.createElement('div');warning.style.cssText='margin-top:7px;font-size:12px;color:#a34e0a';box.appendChild(warning);\n  function repaint(){\n    var answer=getVal(iid,field.key),active=__tmhNoticeApplies(field,answer,iid);\n    box.style.display=active?'block':'none';if(!active)return;\n    var v=getVal(iid,key+'status');status.value=v;yes.style.display=v==='Да'?'block':'none';no.style.display=v==='Нет'?'block':'none';\n    thumbnail.style.display=getVal(iid,key+'photo')?'inline-block':'none';\n    warning.textContent=v==='Да'&&n.requirePhoto!==false&&!getVal(iid,key+'photo')?'⚠ Приложите фото подтверждения':\n      v==='Нет'&&n.requireReason!==false&&!String(getVal(iid,key+'reason')||'').trim()?'⚠ Укажите причину':\n      !v?'⚠ Укажите, передано ли уведомление':'';\n  }\n  status.onchange=function(){\n    setVal(iid,key+'status',this.value);setVal(iid,key+'time',this.value?new Date().toISOString():'');\n    repaint();updateNoticeList();updateNoticeCount();\n  };\n  reason.oninput=function(){setVal(iid,key+'reason',this.value);repaint();};\n  file.onchange=function(){__tmhNoticeFile(this.files&&this.files[0],function(photo){\n    setVal(iid,key+'photo',photo);repaint();updateStats();\n  });};\n  var answerControl=row.querySelector('select[data-field-key],input[data-field-key]');\n  if(answerControl){answerControl.addEventListener('change',function(){setTimeout(function(){repaint();updateNoticeList();updateNoticeCount();},0);});}\n  box.__repaint=repaint;\n  row.appendChild(box);repaint();return row;\n};\ndocument.addEventListener('change',function(event){\n  if(!event.target||event.target.classList&&event.target.classList.contains('tmh-notification-control'))return;\n  setTimeout(function(){\n    document.querySelectorAll('.tmh-notification-control').forEach(function(box){if(box.__repaint)box.__repaint();});\n    updateNoticeList();updateNoticeCount();\n  },0);\n},true);\nvar __tmhBaseUpdateNoticeList=updateNoticeList;\nupdateNoticeList=function(){\n  __tmhBaseUpdateNoticeList();\n  var list=document.getElementById('noticeList'),empty=document.getElementById('emptyMsg');if(!list)return;\n  var items=__tmhNoticeItems();if(items.length&&empty)empty.style.display='none';\n  items.forEach(function(x){\n    var entry=document.createElement('div');entry.className='item';entry.style.cursor='pointer';\n    var text=document.createElement('span');text.textContent=x.eq.title+' / '+(x.inst.section||'')+' / '+(x.inst.block||'')+' / '+x.field.label;\n    var badge=document.createElement('span');badge.className='highlight';\n    badge.textContent=x.status==='Да'?'✓ Уведомление передано':x.status==='Нет'?'⚠ Не передано':'⚠ Требуется уведомление';\n    entry.appendChild(text);entry.appendChild(badge);\n    entry.onclick=function(){var card=Array.from(document.querySelectorAll('.inst[data-iid]')).find(function(c){return c.dataset.iid===x.iid;});if(card){card.scrollIntoView({behavior:'smooth',block:'center'});highlightCard(card);}};\n    list.appendChild(entry);\n  });\n};\nvar __tmhBaseNoticeCount=updateNoticeCount;\nupdateNoticeCount=function(){\n  __tmhBaseNoticeCount();\n  var badge=document.getElementById('noticeCount');\n  if(badge)badge.textContent=Number(badge.textContent||0)+__tmhNoticeItems().length;\n};\nfunction __tmhNoticeExcel(workbook){\n  var ws=workbook.addWorksheet('Уведомления'),items=__tmhNoticeItems();\n  ws.columns=[\n    {header:'Дата осмотра',key:'date',width:17},{header:'Серия',key:'type',width:15},\n    {header:'Номер',key:'number',width:14},{header:'Оборудование',key:'equipment',width:29},\n    {header:'Секция',key:'section',width:19},{header:'Точка / блок',key:'block',width:21},\n    {header:'Операция',key:'operation',width:48},{header:'Ответ',key:'answer',width:22},\n    {header:'Требуется',key:'needed',width:16},{header:'Передано',key:'status',width:18},\n    {header:'Время отметки',key:'time',width:24},{header:'Причина, если не передано',key:'reason',width:40},\n    {header:'Фото подтверждения',key:'photo',width:21}\n  ];\n  ws.getRow(1).font={bold:true,color:{argb:'FFFFFFFF'}};\n  ws.getRow(1).fill={type:'pattern',pattern:'solid',fgColor:{argb:'FF0A5EB0'}};\n  items.forEach(function(x){\n    var row=ws.addRow({\n      date:STATE.general.date||'',type:STATE.general.type||'',number:STATE.general.number||'',\n      equipment:x.eq.title,section:x.inst.section||'',block:x.inst.block||'',\n      operation:x.field.label,answer:x.answer,needed:'Да',status:x.status||'Не указано',\n      time:x.time||'',reason:x.reason||'',photo:x.photo?'Фото приложено':'Нет фото'\n    });\n    row.height=x.photo?65:25;\n    if(x.status!=='Да')row.getCell(10).font={color:{argb:'FFB3261E'},bold:true};\n    if(x.photo&&/^data:image\\/(jpeg|png);base64,/.test(x.photo)){\n      try{\n        var extension=x.photo.indexOf('image/png')>=0?'png':'jpeg';\n        var imageId=workbook.addImage({base64:x.photo,extension:extension});\n        ws.addImage(imageId,{tl:{col:12.08,row:row.number-1+.08},br:{col:12.95,row:row.number-.06}});\n      }catch(error){console.warn('Фото уведомления не встроено',error);}\n    }\n  });\n  ws.autoFilter={from:{row:1,column:1},to:{row:Math.max(2,items.length+1),column:13}};\n  ws.views=[{state:'frozen',ySplit:1}];\n}\n";
